1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="My Page">
7	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
8	  <meta name="theme-color" content="#111214" media="(prefers-color-scheme: dark)">
9	  <meta property="og:title" content="My Page">
10	  <meta property="og:description" content="My Page">
11	  <meta property="og:type" content="website">
12	  <link rel="icon" href="data:,">
13	  <title>My Page</title>
14	  <style>
15	    :root {
16	      color-scheme: light dark;
17	      --bg: #ffffff;
18	      --fg: #1a1a1a;
19	      --muted: #555;
20	      --accent: #2563eb;
21	      --border: #e5e7eb;
22	    }
23	
24	    @media (prefers-color-scheme: dark) {
25	      :root {
26	        --bg: #111214;
27	        --fg: #e8e8e8;
28	        --muted: #aaa;
29	        --accent: #60a5fa;
30	        --border: #2a2b2e;
31	      }
32	    }
33	
34	    * {
35	      box-sizing: border-box;
36	    }
37	
38	    html {
39	      scroll-behavior: smooth;
40	    }
41	
42	    @media (prefers-reduced-motion: reduce) {
43	      html {
44	        scroll-behavior: auto;
45	      }
46	    }
47	
48	    ::selection {
49	      background: var(--accent);
50	      color: var(--bg);
51	    }
52	
53	    body {
54	      font-family: system-ui, -apple-system, sans-serif;
55	      max-width: 40rem;
56	      margin: 3rem auto;
57	      padding: 0 1rem;
58	      line-height: 1.6;
59	      color: var(--fg);
60	      background: var(--bg);
61	    }
62	
63	    h1 {
64	      font-size: 2rem;
65	      margin-bottom: 0.5rem;
66	    }
67	
68	    p {
69	      color: var(--muted);
70	    }
71	
72	    a {
73	      color: var(--accent);
74	    }
75	
76	    a:focus-visible,
77	    button:focus-visible {
78	      outline: 2px solid var(--accent);
79	      outline-offset: 2px;
80	    }
81	
82	    .skip-link {
83	      position: absolute;
84	      left: -9999px;
85	      top: 0;
86	      background: var(--accent);
87	      color: var(--bg);
88	      padding: 0.5rem 1rem;
89	      border-radius: 0.25rem;
90	      z-index: 10;
91	    }
92	
93	    .skip-link:focus {
94	      left: 1rem;
95	      top: 1rem;
96	    }
97	
98	    nav ul {
99	      display: flex;
100	      gap: 1rem;
101	      list-style: none;
102	      padding: 0;
103	      margin: 0 0 2rem;
104	    }
105	
106	    nav a {
107	      text-decoration: none;
108	      font-weight: 500;
109	    }
110	
111	    nav a:hover {
112	      text-decoration: underline;
113	    }
114	
115	    h2 {
116	      margin-top: 2rem;
117	      margin-bottom: 0.5rem;
118	    }
119	
120	    section + section {
121	      margin-top: 1.5rem;
122	    }
123	
124	    footer {
125	      margin-top: 3rem;
126	      padding-top: 1.5rem;
127	      border-top: 1px solid var(--border);
128	      font-size: 0.875rem;
129	      color: var(--muted);
130	    }
131	  </style>
132	</head>
133	<body>
134	  <a class="skip-link" href="#main">Skip to content</a>
135	  <nav aria-label="Primary">
136	    <ul>
137	      <li><a href="#main">Home</a></li>
138	      <li><a href="#about">About</a></li>
139	      <li><a href="#contact">Contact</a></li>
140	    </ul>
141	  </nav>
142	  <main id="main">
143	    <h1>My Page</h1>
144	    <p>Welcome. This page is a starting point — replace this text with your own content.</p>
145	
146	    <section id="about">
147	      <h2>About</h2>
148	      <p>Add a short description of what this page or project is about here.</p>
149	    </section>
150	
151	    <section id="contact">
152	      <h2>Contact</h2>
153	      <p>Reach out at <a href="mailto:hello@example.com">hello@example.com</a>.</p>
154	    </section>
155	  </main>
156	  <footer>
157	    <p>&copy; <span id="year"></span> My Page. All rights reserved.</p>
158	  </footer>
159	  <script>
160	    document.getElementById('year').textContent = String(new Date().getFullYear());
161	  </script>
162	</body>
163	</html>
